  ({ className = "", onClick, value, ...props }, ref) => {
    const { setValue, value: current } = useTabs();
    const isActive = current === value;
    const cls = [
      "ext-tabs-trigger",
      isActive ? "ext-tabs-trigger--active" : "",
      className,
    ]
